solutions.naive:
class Solution:
    def findDuplicates(self, nums: list[int]) -> list[int]:
        ans = []
        for x in range(1, len(nums) + 1):
            if sum(1 for y in nums if y == x) == 2:
                ans.append(x)
        return ans

solutions.better:
class Solution:
    def findDuplicates(self, nums: list[int]) -> list[int]:
        seen, ans = set(), []
        for x in nums:
            if x in seen:
                ans.append(x)
            else:
                seen.add(x)
        return ans

